// Generates src/bundled.generated.ts from bundled/profiles/*.yaml and bundled/packs/*.yaml.
//
// Why: the CLI ships as one bundled JS file and cannot read YAML from disk at runtime, so the
// starter profiles and the `core` pack are embedded as string constants. The generated file is
// committed; scripts/gen-bundled.test.mjs fails when it is stale.
//
// Usage: pnpm --filter @prosegate/profiles gen:bundled

import { readdirSync, readFileSync, realpathSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { parseProfile } from "../src/profile.js";
import { parseRulePack } from "../src/rulepack.js";
import { parseYamlStrict, MAX_PROFILE_BYTES, MAX_PROFILE_NODES, MAX_PACK_BYTES, MAX_PACK_NODES } from "../src/yaml.js";

const here = dirname(fileURLToPath(import.meta.url));
export const PROFILES_DIR = join(here, "..", "bundled", "profiles");
export const PACKS_DIR = join(here, "..", "bundled", "packs");
export const OUTPUT_FILE = join(here, "..", "src", "bundled.generated.ts");

/** `pr-description.yaml` -> `PR_DESCRIPTION_YAML` (profiles); `core.yaml` -> `CORE_PACK_YAML` (packs). */
export function constantName(file, kind) {
  const base = file.replace(/\.yaml$/, "").replace(/-/g, "_").toUpperCase();
  return kind === "pack" ? `${base}_PACK_YAML` : `${base}_YAML`;
}

/** The full text of the generated module. Line endings are normalised to LF. */
export function render({ profilesDir = PROFILES_DIR, packsDir = PACKS_DIR } = {}) {
  const parsed = [], profiles = [], packs = [];
  const lines = [
    "// GENERATED by scripts/gen-bundled.mjs from bundled/profiles/*.yaml and bundled/packs/*.yaml. Do not edit by hand.",
    "// Regenerate with: pnpm --filter @prosegate/profiles gen:bundled",
    "",
  ];
  for (const [dir, kind] of [
    [profilesDir, "profile"],
    [packsDir, "pack"],
  ]) {
    const files = readdirSync(dir)
      .filter((f) => f.endsWith(".yaml"))
      .sort();
    for (const file of files) {
      const text = readFileSync(join(dir, file), "utf8").replace(/\r\n/g, "\n");
      // Build with the same full limits, schemas and injection filter as custom
      // content. Never consult the previous generated cache while regenerating.
      const document = parseYamlStrict(text, kind === "profile" ? MAX_PROFILE_BYTES : MAX_PACK_BYTES,
        kind === "profile" ? MAX_PROFILE_NODES : MAX_PACK_NODES, false);
      if (!document.ok) throw new Error(`Invalid bundled YAML: ${file}`);
      const checked = kind === "profile" ? parseProfile(document.value) : parseRulePack(document.value);
      if (!checked.ok) throw new Error(`Invalid bundled ${kind}: ${file}: ${checked.error.message}`);
      const name = constantName(file, kind);
      const entry = (value) => `[${name}]: ${JSON.stringify(JSON.stringify(value))}`;
      parsed.push(entry(document.value));
      (kind === "profile" ? profiles : packs).push(entry(checked.value));
      lines.push(`export const ${name} = ${JSON.stringify(text)};`, "");
    }
  }
  for (const [name, entries] of [["BUNDLED_PARSED_JSON", parsed], ["BUNDLED_VALIDATED_PROFILE_JSON", profiles], ["BUNDLED_VALIDATED_PACK_JSON", packs]]) {
    lines.push(`export const ${name}: Readonly<Record<string, string>> = Object.freeze({${entries.join(",")}});`, "");
  }
  return lines.join("\n");
}

function main() {
  writeFileSync(OUTPUT_FILE, render());
  process.stdout.write(`wrote ${OUTPUT_FILE}\n`);
}

const entry = process.argv[1];
if (entry && realpathSync(fileURLToPath(import.meta.url)) === realpathSync(entry)) main();
